                    continue;
                }
                edgeCounts[edgeId] = edgeCounts.GetValueOrDefault(edgeId) + 1;
                edges.Add((edgeId, from, to));
            }
            foreach (var entry in edgeCounts)
                if (entry.Value > 1) AddFinding("GRAPH_EDGE_ID_DUPLICATE", entry.Key);
            edges = edges.OrderBy(edge => edge.EdgeId, StringComparer.Ordinal)
                .ThenBy(edge => edge.From, StringComparer.Ordinal)
                .ThenBy(edge => edge.To, StringComparer.Ordinal).ToList();
            foreach (var edge in edges)
            {
                if (!nodeSet.Contains(edge.From)) AddFinding("GRAPH_EDGE_SOURCE_UNRESOLVED", edge.EdgeId);
                if (!nodeSet.Contains(edge.To)) AddFinding("GRAPH_EDGE_TARGET_UNRESOLVED", edge.EdgeId);
            }

            List<string> NormalizeDeclaredNodes(JsonArray values, string invalidCode, string invalidIdentityCode)
            {
                foreach (var declared in values)
                {
                    var nodeId = declared is JsonValue nodeValue && nodeValue.TryGetValue<string>(out var nodeText) ? nodeText : null;
                    if (string.IsNullOrEmpty(nodeId)) AddFinding(invalidIdentityCode, declared?.ToJsonString() ?? "");
                }
                var normalized = values.Select(item => item is JsonValue nodeValue && nodeValue.TryGetValue<string>(out var nodeText) ? nodeText : null)
                    .Where(id => !string.IsNullOrEmpty(id))
                    .Distinct(StringComparer.Ordinal)
                    .OrderBy(id => id, StringComparer.Ordinal).Cast<string>().ToList();
                foreach (var nodeId in normalized)
                    if (!nodeSet.Contains(nodeId)) AddFinding(invalidCode, nodeId);
                return normalized.Where(nodeSet.Contains).ToList();
            }

            var rootNodeIds = NormalizeDeclaredNodes(declaredRootNodeIds, "GRAPH_ROOT_NODE_UNRESOLVED", "GRAPH_ROOT_NODE_ID_INVALID");
            var terminalNodeIds = NormalizeDeclaredNodes(declaredTerminalNodeIds, "GRAPH_TERMINAL_NODE_UNRESOLVED", "GRAPH_TERMINAL_NODE_ID_INVALID");
            var terminalNodeSet = terminalNodeIds.ToHashSet(StringComparer.Ordinal);

            findings = findings.OrderBy(finding => finding.Code, StringComparer.Ordinal)
                .ThenBy(finding => finding.SubjectId, StringComparer.Ordinal).ToList();
            if (findings.Count > 0)
            {
                return new JsonObject
                {
                    ["disposition"] = "REJECTED",
                    ["nodeIds"] = ToArray(nodeIds),
                    ["edgeIds"] = ToArray(edges.Select(edge => edge.EdgeId).Distinct(StringComparer.Ordinal).OrderBy(id => id, StringComparer.Ordinal).ToList()),
                    ["rootNodeIds"] = ToArray(rootNodeIds),
                    ["terminalNodeIds"] = ToArray(terminalNodeIds),
                    ["reachableNodeIds"] = new JsonArray(),
                    ["unreachableNodeIds"] = ToArray(nodeIds),
                    ["traversalNodeIds"] = new JsonArray(),
                    ["traversalEdgeIds"] = new JsonArray(),
                    ["reachablePairs"] = new JsonArray(),
                    ["terminalReachability"] = new JsonArray(),
                    ["cycleComponents"] = new JsonArray(),
                    ["cycleEdgeIds"] = new JsonArray(),
                    ["fixedPointPasses"] = 0,
                    ["findings"] = new JsonArray(findings.Select(finding => (JsonNode?)new JsonObject
                    {
                        ["code"] = finding.Code,
                        ["subjectId"] = finding.SubjectId
                    }).ToArray())
                };
            }

            var adjacency = nodeIds.ToDictionary(id => id, _ => new List<(string EdgeId, string From, string To)>(), StringComparer.Ordinal);
            foreach (var edge in edges) adjacency[edge.From].Add(edge);
            foreach (var nodeId in nodeIds)
                adjacency[nodeId] = adjacency[nodeId].OrderBy(edge => edge.To, StringComparer.Ordinal)
                    .ThenBy(edge => edge.EdgeId, StringComparer.Ordinal).ToList();

            (List<string> Reached, int Passes) ClosureFrom(string startNodeId)
            {
                var reached = new HashSet<string>(StringComparer.Ordinal) { startNodeId };
                var frontier = new List<string> { startNodeId };
                var passes = 0;
                while (frontier.Count > 0)
                {
                    var next = new HashSet<string>(StringComparer.Ordinal);
                    foreach (var nodeId in frontier.OrderBy(id => id, StringComparer.Ordinal))
                        foreach (var edge in adjacency[nodeId])
                            if (reached.Add(edge.To)) next.Add(edge.To);
                    frontier = next.ToList();
                    passes++;
                }
                return (reached.OrderBy(id => id, StringComparer.Ordinal).ToList(), passes);
            }

            var closures = nodeIds.ToDictionary(id => id, ClosureFrom, StringComparer.Ordinal);
            var reachablePairs = nodeIds.SelectMany(from => closures[from].Reached
                .Select(to => (JsonNode?)new JsonObject { ["from"] = from, ["to"] = to })).ToArray();
            var reachableNodeSet = new HashSet<string>(rootNodeIds.SelectMany(root => closures[root].Reached), StringComparer.Ordinal);
            var reachableNodeIds = reachableNodeSet.OrderBy(id => id, StringComparer.Ordinal).ToList();
            var unreachableNodeIds = nodeIds.Where(id => !reachableNodeSet.Contains(id)).ToList();

            var traversalNodeIds = new List<string>();
            var traversalEdgeIds = new List<string>();
            var traversedNodes = new HashSet<string>(StringComparer.Ordinal);
            var traversedEdges = new HashSet<string>(StringComparer.Ordinal);
            var frontierNodes = rootNodeIds.ToList();
            while (frontierNodes.Count > 0)
            {
                var nodeId = frontierNodes[0];
                frontierNodes.RemoveAt(0);
                if (!traversedNodes.Add(nodeId)) continue;
                traversalNodeIds.Add(nodeId);
                foreach (var edge in adjacency[nodeId])
                {
                    if (traversedEdges.Add(edge.EdgeId)) traversalEdgeIds.Add(edge.EdgeId);
                    if (!traversedNodes.Contains(edge.To)) frontierNodes.Add(edge.To);
                }
                frontierNodes.Sort(StringComparer.Ordinal);
            }

            var terminalReachability = nodeIds.Select(nodeId => (JsonNode?)new JsonObject
            {
                ["nodeId"] = nodeId,
                ["terminalNodeIds"] = new JsonArray(closures[nodeId].Reached
                    .Where(terminalNodeSet.Contains).Select(id => JsonValue.Create(id)).ToArray())
            }).ToArray();

            var assignedCycleNodes = new HashSet<string>(StringComparer.Ordinal);
            var cycleComponents = new List<List<string>>();
            foreach (var nodeId in nodeIds)
            {
                if (assignedCycleNodes.Contains(nodeId)) continue;
                var mutuallyReachable = nodeIds.Where(peerNodeId =>
                    closures[nodeId].Reached.Contains(peerNodeId) && closures[peerNodeId].Reached.Contains(nodeId)).ToList();
                var hasSelfLoop = edges.Any(edge => edge.From == nodeId && edge.To == nodeId);
                if (mutuallyReachable.Count > 1 || hasSelfLoop)
                {
                    foreach (var member in mutuallyReachable) assignedCycleNodes.Add(member);
                    cycleComponents.Add(mutuallyReachable);
                }
            }
            cycleComponents = cycleComponents.OrderBy(component => string.Join("\u0000", component), StringComparer.Ordinal).ToList();
            var cycleComponentByNode = new Dictionary<string, int>(StringComparer.Ordinal);
            for (var index = 0; index < cycleComponents.Count; index++)
                foreach (var member in cycleComponents[index]) cycleComponentByNode[member] = index;
            var cycleEdgeIds = edges
                .Where(edge => cycleComponentByNode.ContainsKey(edge.From)
                    && cycleComponentByNode[edge.From] == cycleComponentByNode.GetValueOrDefault(edge.To, -1))
                .Select(edge => edge.EdgeId).OrderBy(id => id, StringComparer.Ordinal).ToList();

            return new JsonObject
            {
                ["disposition"] = "CLOSED",
                ["nodeIds"] = ToArray(nodeIds),
                ["edgeIds"] = new JsonArray(edges.Select(edge => JsonValue.Create(edge.EdgeId)).ToArray()),
                ["rootNodeIds"] = ToArray(rootNodeIds),
                ["terminalNodeIds"] = ToArray(terminalNodeIds),
                ["reachableNodeIds"] = ToArray(reachableNodeIds),
                ["unreachableNodeIds"] = ToArray(unreachableNodeIds),
                ["traversalNodeIds"] = ToArray(traversalNodeIds),
                ["traversalEdgeIds"] = ToArray(traversalEdgeIds),
                ["reachablePairs"] = new JsonArray(reachablePairs),
                ["terminalReachability"] = new JsonArray(terminalReachability),
                ["cycleComponents"] = new JsonArray(cycleComponents.Select(component =>
                    (JsonNode?)new JsonArray(component.Select(id => JsonValue.Create(id)).ToArray())).ToArray()),
                ["cycleEdgeIds"] = ToArray(cycleEdgeIds),
                ["fixedPointPasses"] = Math.Max(0, closures.Values.Select(closure => closure.Passes).DefaultIfEmpty(0).Max()),
                ["findings"] = new JsonArray()
            };
        }

        private static JsonArray AsListOrEmpty(JsonObject graph, string key) => graph[key] as JsonArray ?? new JsonArray();

        private static JsonArray ToArray(IEnumerable<string> values) =>
            new(values.Select(value => JsonValue.Create(value)).ToArray());

        private static JsonArray AsArray(JsonNode? value) =>
            value as JsonArray ?? throw NotAdmitted("OPERAND_NOT_ARRAY");

        private static bool TryNumber(JsonNode? value, out double number)
        {
            if (value is JsonValue scalar) return TryNumber(scalar, out number);
            number = 0;
            return false;
        }

        private static bool TryNumber(JsonValue scalar, out double number)
        {
            number = 0;
            if (scalar.TryGetValue<double>(out var asDouble)) { number = asDouble; return true; }
            if (scalar.TryGetValue<int>(out var asInt)) { number = asInt; return true; }
            if (scalar.TryGetValue<long>(out var asLong)) { number = asLong; return true; }
            if (scalar.TryGetValue<decimal>(out var asDecimal)) { number = (double)asDecimal; return true; }
            return false;
        }

        private static bool IsString(JsonNode? value) =>
            value is JsonValue scalar && scalar.TryGetValue<string>(out _);

        private static string AsString(JsonNode? value) =>
            value is JsonValue scalar && scalar.TryGetValue<string>(out var text) ? text : "";

        private static string CoerceText(JsonNode? value)
        {
            if (value is null) return "null";
            if (value is JsonValue scalar)
            {
                if (scalar.TryGetValue<bool>(out var flag)) return flag ? "true" : "false";
                if (TryNumber(scalar, out var number)) return NumberText(number);
                if (scalar.TryGetValue<string>(out var text)) return text;
                return "[object Object]";
            }
            if (value is JsonArray array) return string.Join(",", array.Select(CoerceText));
            return "[object Object]";
        }

        private static string NumberText(double value)
        {
            if (double.IsNaN(value)) return "NaN";
            if (value == 0) return "0";
            if (value == Math.Truncate(value) && Math.Abs(value) < 1e15)
                return ((long)value).ToString(CultureInfo.InvariantCulture);
            return value.ToString("R", CultureInfo.InvariantCulture);
        }
    }

    public sealed class ExecuteOptions
    {
        public JsonObject? PortOutcomes { get; init; }
        public JsonObject? GraphOutcomes { get; init; }
        public JsonObject? GraphOutcomeCatalog { get; init; }
        public GovernedEffectContext? EffectContext { get; init; }
        public string? RootExecutionId { get; init; }
        public CancellationToken CancellationToken { get; init; }
    }

    public static async Task<JsonObject> ExecuteAsync(JsonNode? input, ExecuteOptions? options = null)
    {
        options ??= new ExecuteOptions();
        var effectContext = options.EffectContext ?? new GovernedEffectContext();
        var occurrenceByCell = new Dictionary<string, int>(StringComparer.Ordinal);
        var fixtureOccurrence = new Dictionary<string, int>(StringComparer.Ordinal);

        GraphBindingProjector projectBinding = (bindingAuthorityId, value, cancellationToken) =>
        {
            if (EdgeExpressions.TryGetValue(bindingAuthorityId, out var evaluate))
            {
                var scope = new Dictionary<string, JsonNode?>(StringComparer.Ordinal)
                {
                    ["input"] = value,
                    ["root"] = input
                };
                return ValueTask.FromResult(evaluate(scope));
            }
            if (DeclarativeOutputs.TryGetValue(bindingAuthorityId, out var output))
                return ValueTask.FromResult(output?.DeepClone());
            throw new InvalidOperationException("EDGE_BINDING_REALIZATION_MISSING: '" + bindingAuthorityId + "'.");
        };

        var providers = new Dictionary<string, GraphProvider>(StringComparer.Ordinal)
        {
            [SemanticValueProfileId] = (value, context, cancellationToken) =>
                ValueTask.FromResult(InvokeSemanticValue(value, context, occurrenceByCell, fixtureOccurrence, options)),
            [PlatformEffectProfileId] = CreateEffectProvider(effectContext, options, fixtureOccurrence)
        };

        var admission = ContractCatalog["contracts"] is JsonObject contracts && contracts.Count > 0
            ? new SemanticContractCatalogAdmission(ContractCatalog)
            : null;
        try
        {
            var scheduler = new SemanticExecutionGraphScheduler(
                Plan,
                providers,
                projectBinding,
                admission is null ? null : admission.AdmitsAsync);
            var graphResult = await scheduler.ExecuteAsync(input, options.RootExecutionId, options.CancellationToken);
            return ComposeExecution(graphResult);
        }
        finally
        {
            admission?.Dispose();
        }
    }

    private static GraphProviderOutcome? TryResolveFixtureOutcome(
        JsonNode? input,
        GraphExecutionContext context,
        Dictionary<string, int> fixtureOccurrence,
        ExecuteOptions options)
    {
        var scenarioId = TerminalCells.TryGetValue(context.CellId, out var foundScenario) ? foundScenario : null;
        var configuration = context.Configuration;
        var cell = CellsById.TryGetValue(context.CellId, out var foundCell) ? foundCell : null;
        var portId = configuration?["kind"]?.GetValue<string>() == "invoke-port" && configuration["portId"] is JsonValue portValue
            ? portValue.GetValue<string>()
            : cell is null ? null : cell["semanticAddress"]!.GetValue<string>().Split("#/")[0];
        JsonNode? declared = null;
        if (scenarioId is not null && options.GraphOutcomes is not null && options.GraphOutcomes[scenarioId] is JsonNode graphDeclared)
        {
            declared = graphDeclared;
        }
        else if (portId is not null && options.PortOutcomes is not null && options.PortOutcomes[portId] is JsonNode portDeclared)
        {
            declared = new JsonObject { ["outcomeValue"] = FixturePortOutput(portId, portDeclared, input) };
        }
        if (declared is null) return null;
        var occurrenceKey = scenarioId ?? portId ?? context.CellId;
        var occurrence = fixtureOccurrence.TryGetValue(occurrenceKey, out var currentOccurrence) ? currentOccurrence : 0;
        fixtureOccurrence[occurrenceKey] = occurrence + 1;
        var selected = declared is JsonArray declaredArray
            ? declaredArray[Math.Min(occurrence, declaredArray.Count - 1)]
            : declared;
        if (selected is not JsonObject selectedObject)
            throw new InvalidOperationException("FIXTURE_GRAPH_OUTCOME_INVALID: '" + occurrenceKey + "'.");
        JsonNode? referencedValue = null;
        if (selectedObject["outcomeRef"] is JsonValue outcomeRefValue)
        {
            var outcomeRef = outcomeRefValue.GetValue<string>();
            referencedValue = options.GraphOutcomeCatalog?[outcomeRef];
            if (referencedValue is null)
                throw new InvalidOperationException("FIXTURE_GRAPH_OUTCOME_REFERENCE_MISSING: '" + outcomeRef + "'.");
        }
        var outcomeVariant = selectedObject["outcomeVariant"]?.GetValue<string>();
        var fixtureValue = ResolveFixtureGraphValue(
            selectedObject["outcomeValue"]?.DeepClone()
                ?? referencedValue?.DeepClone()
                ?? WithOutcomeVariant(input, outcomeVariant)?.DeepClone(),
            options.GraphOutcomeCatalog ?? new JsonObject());
        var outcomeDisposition = selectedObject["disposition"]?.GetValue<string>() ?? "completed";
        return new GraphProviderOutcome(fixtureValue?.DeepClone(), outcomeVariant, outcomeDisposition);
    }

    private static GraphProviderOutcome InvokeSemanticValue(
        JsonNode? input,
        GraphExecutionContext context,
        Dictionary<string, int> occurrenceByCell,
        Dictionary<string, int> fixtureOccurrence,
        ExecuteOptions options)
    {
        var fixtureOutcome = TryResolveFixtureOutcome(input, context, fixtureOccurrence, options);
        if (fixtureOutcome is not null) return fixtureOutcome;
        var configuration = context.Configuration;
        var cell = CellsById.TryGetValue(context.CellId, out var foundCell) ? foundCell : null;
        var bindingConfiguration = configuration?["binding"]?["configuration"] as JsonObject;
        var expression = bindingConfiguration?["expression"] as JsonObject
            ?? (configuration is not null && configuration["op"] is JsonValue ? configuration : null);
        if (expression is not null && expression["op"] is JsonValue)
        {
            if (!PureCells.TryGetValue(context.CellId, out var evaluate))
                throw new InvalidOperationException("CAPABILITY_PROJECTION_MECHANIC_UNRESOLVED: '" + expression["op"]!.GetValue<string>() + "'");
            var transformationInput = context.DecompositionInput ?? input;
            var scope = new Dictionary<string, JsonNode?>(StringComparer.Ordinal)
            {
                ["input"] = transformationInput,
                ["root"] = context.RootInput ?? transformationInput
            };
            JsonNode? outcomeValue;
            try
            {
                outcomeValue = evaluate(scope);
            }
            catch
            {
                return new GraphProviderOutcome(input?.DeepClone(), "VALUE");
            }
            if (CollectionOperators.Contains(expression["op"]!.GetValue<string>()))
            {
                var occurrence = occurrenceByCell.TryGetValue(context.CellId, out var currentOccurrence) ? currentOccurrence : 0;
                occurrenceByCell[context.CellId] = occurrence + 1;
                JsonNode? source = null;
                try
                {
                    if (CollectionSources.TryGetValue(context.CellId, out var sourceEvaluate)) source = sourceEvaluate(scope);
                }
                catch
                {
                    source = null;
                }
                var iterations = source is JsonArray sourceArray ? sourceArray.Count : 0;
                return new GraphProviderOutcome(outcomeValue, occurrence < iterations ? "CONTINUE" : "STOP");
            }
            return new GraphProviderOutcome(outcomeValue);
        }
        if (configuration?["kind"]?.GetValue<string>() == "invoke-port" && configuration["binding"] is JsonObject sourceBinding)
        {
            var platformCapabilityId = sourceBinding["platformCapabilityId"]?.GetValue<string>() ?? "";
            var sourceConfiguration = sourceBinding["configuration"] as JsonObject ?? new JsonObject();
            if (platformCapabilityId == "sda-declarative-value-port.v1")
                return new GraphProviderOutcome(sourceConfiguration["outcome"]?.DeepClone());
            throw new InvalidOperationException("MISSING_SDA_PLATFORM_CAPABILITY: '" + platformCapabilityId + "'");
        }
        if (cell?["execution"]?["authorityId"]?.GetValue<string>() == "mechanic:identity.v1")
            return new GraphProviderOutcome(input?.DeepClone(), "VALUE");
        throw new InvalidOperationException("UNDECLARED_EXECUTION_MECHANIC: '" + context.CellId + "'.");
    }

    private static GraphProvider CreateEffectProvider(
        GovernedEffectContext effectContext,
        ExecuteOptions options,
        Dictionary<string, int> fixtureOccurrence) =>
        async (input, context, cancellationToken) =>
        {
            var fixtureOutcome = TryResolveFixtureOutcome(input, context, fixtureOccurrence, options);
            if (fixtureOutcome is not null) return fixtureOutcome;
            var binding = context.Configuration?["binding"] as JsonObject;
            var configuration = binding?["configuration"] as JsonObject ?? context.Configuration ?? new JsonObject();
            var mechanicId = binding?["platformCapabilityId"]?.GetValue<string>() ?? string.Empty;
            if (configuration["invocationCondition"] is JsonObject condition)
            {
                if (condition["path"] is not JsonValue conditionPath
                    || !condition.ContainsKey("equals")
                    || condition["whenFalse"]?.GetValue<string>() != "preserve-carrier")
                    throw new InvalidOperationException("DIRECT_PROVIDER_INVOCATION_CONDITION_INVALID");
                if (!JsonNode.DeepEquals(Sfx.ValueAt(input, conditionPath.GetValue<string>()), condition["equals"]))
                    return new GraphProviderOutcome(input?.DeepClone());
            }
            if (configuration["requestPath"] is not null || configuration["resultPath"] is not null)
            {
                if (configuration["requestPath"] is not JsonValue requestPathValue || configuration["resultPath"] is not JsonValue resultPathValue)
                    throw new InvalidOperationException("DIRECT_PROVIDER_CARRIER_BINDING_INVALID");
                var request = Sfx.ValueAt(input, requestPathValue.GetValue<string>());
                if (request is null)
                    throw new InvalidOperationException("DIRECT_PROVIDER_REQUEST_PATH_MISSING: '" + requestPathValue.GetValue<string>() + "'");
                var bound = await GovernedEffectPorts.DispatchAsync(
                    mechanicId, configuration, request, context, null, cancellationToken, effectContext);
                return new GraphProviderOutcome(BindValueAt(input, resultPathValue.GetValue<string>(), bound));
            }
            var outcome = await GovernedEffectPorts.DispatchAsync(
                mechanicId, configuration, input, context, null, cancellationToken, effectContext);
            return new GraphProviderOutcome(outcome);
        };

    private static JsonNode? BindValueAt(JsonNode? source, string dottedPath, JsonNode? value)
    {
        var segments = dottedPath.Split('.', StringSplitOptions.RemoveEmptyEntries);
        if (segments.Length == 0) throw new InvalidOperationException("PROJECTED_CAPABILITY_RESULT_PATH_MISSING");
        if (segments.Any(segment => segment is "__proto__" or "prototype" or "constructor"))
            throw new InvalidOperationException("PROJECTED_CAPABILITY_RESULT_PATH_INVALID: '" + dottedPath + "'");
        var result = source?.DeepClone() ?? new JsonObject();
        var target = result;
        foreach (var segment in segments.Take(segments.Length - 1))
        {
            if (target[segment] is JsonObject existing)
            {
                target = existing;
            }
            else if (target[segment] is null)
            {
                var created = new JsonObject();
                target[segment] = created;
                target = created;
            }
            else
            {
                throw new InvalidOperationException("PROJECTED_CAPABILITY_RESULT_PATH_INVALID: '" + dottedPath + "'");
            }
        }
        target[segments[^1]] = value?.DeepClone();
        return result;
    }

    private static JsonNode? FixturePortOutput(string portId, JsonNode declared, JsonNode? input)
    {
        var selected = declared is JsonObject declaredObject && declaredObject["byCarrierType"] is JsonObject byCarrierType
            ? (input is JsonObject inputObject && inputObject["carrierType"] is JsonValue carrierValue
                ? byCarrierType[carrierValue.GetValue<string>()] ?? declared
                : declared)
            : declared;
        if (selected is not JsonObject selectedObject)
            throw new InvalidOperationException("FIXTURE_PORT_OUTCOME_INVALID: '" + portId + "'.");
        if (selectedObject["status"]?.GetValue<string>() == "FAILURE")
        {
            var errorCode = selectedObject["error"]?["code"]?.GetValue<string>();
            throw new InvalidOperationException(errorCode ?? ("FIXTURE_PORT_FAILURE: '" + portId + "'."));
        }
        if (selectedObject.ContainsKey("output")) return selectedObject["output"]?.DeepClone();
        if (!selectedObject.ContainsKey("status")) return selectedObject.DeepClone();
        throw new InvalidOperationException("FIXTURE_PORT_OUTPUT_MISSING: '" + portId + "'.");
    }

    private static JsonNode? ResolveFixtureGraphValue(JsonNode? value, JsonObject catalog, List<string>? stack = null)
    {
        stack ??= new List<string>();
        if (value is JsonArray array)
        {
            var result = new JsonArray();
            foreach (var item in array) result.Add(ResolveFixtureGraphValue(item, catalog, stack));
            return result;
        }
        if (value is JsonObject target)
        {
            if (target.Count == 1 && target["$fixtureRef"] is JsonValue referenceValue)
            {
                var reference = referenceValue.GetValue<string>();
                if (!catalog.ContainsKey(reference))
                    throw new InvalidOperationException("FIXTURE_GRAPH_OUTCOME_REFERENCE_MISSING: '" + reference + "'.");
                if (stack.Contains(reference))
                    throw new InvalidOperationException("FIXTURE_GRAPH_OUTCOME_REFERENCE_CYCLE: '" + string.Join(" -> ", stack.Append(reference)) + "'.");
                var next = new List<string>(stack) { reference };
                return ResolveFixtureGraphValue(catalog[reference]?.DeepClone(), catalog, next);
            }
            var resolved = new JsonObject();
            foreach (var field in target) resolved[field.Key] = ResolveFixtureGraphValue(field.Value, catalog, stack);
            return resolved;
        }
        return value?.DeepClone();
    }

    private static JsonNode? WithOutcomeVariant(JsonNode? input, string? outcomeVariant)
    {
        if (input is not JsonObject source) return input;
        var clone = source.DeepClone().AsObject();
        if (outcomeVariant is not null) clone["outcomeVariant"] = outcomeVariant;
        return clone;
    }

    private static JsonObject ComposeExecution(JsonObject graphResult)
    {
        var executions = new JsonArray();
        foreach (var item in graphResult["cellTestimony"]!.AsArray())
        {
            if (item?["cellAltitude"]?.GetValue<string>() != "scenario") continue;
            var cellId = item["cellId"]!.GetValue<string>();
            executions.Add(new JsonObject
            {
                ["executionId"] = item["cellExecutionId"]?.DeepClone(),
                ["rootExecutionId"] = graphResult["rootExecutionId"]?.DeepClone(),
                ["parentExecutionId"] = null,
                ["scenarioId"] = ScenarioIdForCell(cellId),
                ["disposition"] = item["disposition"]?.DeepClone(),
                ["outcome"] = null
            });
        }
        var disposition = graphResult["disposition"]!.GetValue<string>();
        return new JsonObject
        {
            ["disposition"] = disposition == "completed" ? "terminated" : disposition,
            ["outcome"] = graphResult["outcome"]?.DeepClone(),
            ["outcomeVariant"] = graphResult["outcomeVariant"]?.DeepClone(),
            ["executions"] = executions,
            ["observations"] = new JsonArray(),
            ["graphExecution"] = graphResult.DeepClone()
        };
    }

    private static string? ScenarioIdForCell(string cellId)
    {
        var cell = CellsById.TryGetValue(cellId, out var found) ? found : null;
        while (cell is not null && cell["altitude"]?.GetValue<string>() != "scenario")
        {
            cell = cell["parentCellId"] is JsonValue parentValue && CellsById.TryGetValue(parentValue.GetValue<string>(), out var parent)
                ? parent : null;
        }
        if (cell is null) return null;
        var segments = cell["semanticAddress"]!.GetValue<string>().Split("/scenario/");
        return segments[^1];
    }

    private static Dictionary<string, JsonObject> BuildCellsById()
    {
        var map = new Dictionary<string, JsonObject>(StringComparer.Ordinal);
        foreach (var cell in CanonicalGraph["cells"]!.AsArray())
            map[cell!["cellId"]!.GetValue<string>()] = cell.AsObject();
        return map;
    }

    private static Dictionary<string, string> FixtureTerminalCells(JsonObject graph)
    {
        var decompositionByParent = new Dictionary<string, JsonObject>(StringComparer.Ordinal);
        foreach (var item in graph["decompositions"]!.AsArray())
            decompositionByParent[item!["parentCellId"]!.GetValue<string>()] = item.AsObject();
        var result = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var node in graph["cells"]!.AsArray())
        {
            var cell = node!.AsObject();
            if (cell["altitude"]?.GetValue<string>() != "scenario") continue;
            var cellId = cell["cellId"]!.GetValue<string>();
            var decomposition = decompositionByParent.TryGetValue(cellId, out var found) ? found : null;
            var exits = decomposition?["exitCellIds"] as JsonArray;
            var cursor = exits is not null && exits.Count > 0 ? exits[^1]!.GetValue<string>() : cellId;
            var scenarioId = ScenarioIdForCell(cellId);
            if (scenarioId is not null) result[cursor] = scenarioId;
        }
        return result;
    }

    public static Task<JsonObject> RunFixtureAsync(string fixtureId, ExecuteOptions? options = null)
    {
        options ??= new ExecuteOptions();
        var fixture = Fixtures["fixtures"] is JsonArray fixtures
            ? fixtures.Select(node => node!.AsObject())
                .FirstOrDefault(candidate => candidate["fixtureId"]?.GetValue<string>() == fixtureId)
            : null;
        if (fixture is null) throw new InvalidOperationException("UNKNOWN_PROJECTED_FIXTURE: '" + fixtureId + "'.");
        var graphOutcomeCatalog = MergeObjects(Fixtures["graphOutcomeCatalog"] as JsonObject, fixture["graphOutcomeCatalog"] as JsonObject);
        var portOutcomes = MergeObjects(Fixtures["portOutcomes"] as JsonObject, fixture["portOutcomes"] as JsonObject);
        var input = ResolveFixtureGraphValue(fixture["input"], graphOutcomeCatalog);
        return ExecuteAsync(input, new ExecuteOptions
        {
            PortOutcomes = portOutcomes,
            GraphOutcomes = fixture["graphOutcomes"] as JsonObject,
            GraphOutcomeCatalog = graphOutcomeCatalog,
            EffectContext = options.EffectContext,
            RootExecutionId = options.RootExecutionId,
            CancellationToken = options.CancellationToken
        });
    }

    private static JsonObject MergeObjects(JsonObject? first, JsonObject? second)
    {
        var result = new JsonObject();
        if (first is not null) foreach (var field in first) result[field.Key] = field.Value?.DeepClone();
        if (second is not null) foreach (var field in second) result[field.Key] = field.Value?.DeepClone();
        return result;
    }

    public static JsonObject Conformance(JsonObject? observedExecution = null)
    {
        var findings = new JsonArray();
        if (observedExecution?["graphExecution"] is JsonObject graphExecution
            && graphExecution["cellTestimony"] is JsonArray cellTestimony
            && graphExecution["edgeTestimony"] is JsonArray edgeTestimony)
        {
            var cellIds = new HashSet<string>(
                CanonicalGraph["cells"]!.AsArray().Select(cell => cell!["cellId"]!.GetValue<string>()), StringComparer.Ordinal);
            var edgeIds = new HashSet<string>(
                CanonicalGraph["edges"]!.AsArray().Select(edge => edge!["edgeId"]!.GetValue<string>()), StringComparer.Ordinal);
            foreach (var item in cellTestimony)
            {
                var cellId = item?["cellId"]?.GetValue<string>() ?? "";
                if (!cellIds.Contains(cellId)) findings.Add(Finding("UNEXPECTED_CELL_EXECUTED", cellId));
                if (CellsById.TryGetValue(cellId, out var cell) && cell["execution"]?["providerSlotId"] is not null
                    && string.IsNullOrEmpty(item?["providerProfileId"]?.GetValue<string>()))
                    findings.Add(Finding("PROVIDER_TESTIMONY_GAP", item?["cellExecutionId"]?.GetValue<string>() ?? ""));
            }
            foreach (var item in edgeTestimony)
            {
                var edgeId = item?["edgeId"]?.GetValue<string>() ?? "";
                if (!edgeIds.Contains(edgeId)) findings.Add(Finding("UNEXPECTED_EDGE_TRAVERSED", edgeId));
            }
        }
        else
        {
            findings.Add(Finding("EXECUTION_NOT_OBSERVED", "execution"));
        }
        var admitted = findings.Count == 0;
        var closures = new JsonObject();
        foreach (var closure in ConformanceClosures)
        {
            var closureId = closure!.GetValue<string>();
            closures[closureId] = new JsonObject
            {
                ["closureId"] = closureId,
                ["disposition"] = admitted ? "PASS" : "FAIL",
                ["findings"] = findings.DeepClone()
            };
        }
        return new JsonObject
        {
            ["queryId"] = "semantic-execution-graph-conformance",
            ["capabilityId"] = CapabilityId,
            ["closures"] = closures,
            ["platformMechanics"] = new JsonObject { ["disposition"] = "RESOLVED", ["resolutions"] = new JsonArray() },
            ["executableOrigin"] = "PROJECTED_ONLY",
            ["admissionDisposition"] = admitted ? "ADMITTED" : "REJECTED",
            ["findings"] = findings
        };
    }

    private static JsonObject Finding(string code, string subjectId) => new()
    {
        ["code"] = code,
        ["subjectId"] = subjectId
    };

    public static async Task<int> RunCliAsync(string[] args)
    {
        var argument = args.Length > 0 ? args[0] : (Console.IsInputRedirected ? Console.In.ReadToEnd().Trim() : "");
        if (argument.StartsWith("--fixture=", StringComparison.Ordinal))
        {
            var fixtureId = argument.Substring("--fixture=".Length);
            var result = await RunFixtureAsync(fixtureId);
            Console.WriteLine(result.ToJsonString(RelaxedJson));
            var fixture = Fixtures["fixtures"] is JsonArray fixtures
                ? fixtures.Select(node => node!.AsObject())
                    .FirstOrDefault(candidate => candidate["fixtureId"]?.GetValue<string>() == fixtureId)
                : null;
            return fixture is not null
                && result["disposition"]?.GetValue<string>() == fixture["expected"]?["disposition"]?.GetValue<string>() ? 0 : 1;
        }
        if (argument.Length == 0) throw new InvalidOperationException("Expected canonical JSON input as one argument or on stdin.");
        JsonNode? parsed;
        try
        {
            parsed = JsonNode.Parse(argument);
        }
        catch (JsonException)
        {
            if (argument.StartsWith("{", StringComparison.Ordinal)
                || argument.StartsWith("[", StringComparison.Ordinal)
                || argument.StartsWith("\"", StringComparison.Ordinal)) throw;
            parsed = JsonValue.Create(argument);
        }
        var execution = await ExecuteAsync(parsed);
        Console.WriteLine(execution.ToJsonString(RelaxedJson));
        var outcome = execution["outcome"] as JsonObject;
        var interfaceExit = outcome?["interfaceExitDisposition"]?.GetValue<string>();
        return execution["disposition"]?.GetValue<string>() != "terminated" || interfaceExit == "NONZERO" ? 1 : 0;
    }
}
